"""Results sections 4.4-4.10 (explanations, size audit, faithfulness, stability, skin tone, external). All numbers read from result files."""
import json, glob
import numpy as np, pandas as pd
from common import *
from ms_results_cls import pm, f3, fp

RES = OUT / 'results'
XA = {int(k): v for k, v in json.load(open(RES / 'xai_all_seeds.json')).items()}
PA = {int(k): v for k, v in json.load(open(RES / 'pad_audit.json')).items()}
DG = {}
for f in glob.glob(str(RES / 'domain_gap_*.json')):
    for k, v in json.load(open(f)).items():
        if k.startswith('seed'): DG[int(k[4:])] = v
SEEDS_X = sorted(XA)
K = len(SEEDS_X)
REF = 42


def g(R, *path):
    for p in path: R = R[p]
    return R


def ac(*path, src=None):
    src = src or XA; v = np.array([g(src[s], *path) for s in sorted(src)], float); return v


def rng_s(v, d=3): return f'{np.nanmin(v):.{d}f} to {np.nanmax(v):.{d}f}'
def ms(v, d=3): return f'{np.nanmean(v):.{d}f} ± {np.nanstd(v, ddof=1):.{d}f}' if len(v) > 1 else f'{v[0]:.{d}f}'
def cnt(v, cond): return int(np.sum(cond(np.asarray(v, float))))
def mi(d, k='median', dd=3): return f'{d[k]:.{dd}f}'
def mq(d, dd=3): return f'{d["median"]:.{dd}f} ({d["q1"]:.{dd}f}–{d["q3"]:.{dd}f})'


def sec_localization(M):
    R = XA[REF]; ct = pd.read_csv(RES / 'ref_class_table.csv')
    M.h(2, '4.4 Explanation localization, correct versus misclassified predictions')
    n_c, n_w = R['n_correct'], R['n_incorrect']
    M.p(f"Grad-CAM++ maps and LSAS were computed for all {R['n']} test images (seed {REF}: {n_c} correctly classified, {n_w} misclassified; all with valid masks). Overall median LSAS was {mq(R['lsas_all'])}; it was {mq(R['lsas_correct'])} for correct and {mq(R['lsas_incorrect'])} for misclassified predictions. Restricting localization analyses to correctly classified images, as is common, could bias conclusions; here the raw LSAS distributions of correct and misclassified images were statistically indistinguishable (Mann–Whitney {fp(R['correct_vs_incorrect']['lsas']['p'])}, rank-biserial r = {R['correct_vs_incorrect']['lsas']['rbc']:+.3f}; consistent in {cnt(ac('correct_vs_incorrect', 'lsas', 'p'), lambda v: v >= 0.05)}/{K} seeds with p ≥ 0.05). The same holds for the area-adjusted excess LSAS (p = {R['correct_vs_incorrect']['e_shuf']['p']:.3f}). Differences appear only in an area-insensitive measure: pixel-wise localization AUC was lower for misclassified images (median {R['correct_vs_incorrect']['loc_auc']['incorrect']['median']:.3f} vs {R['correct_vs_incorrect']['loc_auc']['correct']['median']:.3f}; {fp(R['correct_vs_incorrect']['loc_auc']['p'])}, r = {R['correct_vs_incorrect']['loc_auc']['rbc']:+.3f}; p < 0.05 in {cnt(ac('correct_vs_incorrect', 'loc_auc', 'p'), lambda v: v < 0.05)}/{K} seeds), a small effect. Prediction correctness is predicted by confidence (logistic coefficient {R['logit_correct']['conf']['coef']:.2f}, {fp(R['logit_correct']['conf']['p'])}) but not by LSAS after adjustment for confidence and lesion area ({fp(R['logit_correct']['lsas']['p'])}), and not by excess LSAS ({fp(R['logit_correct_excess']['e_shuf']['p'])}). The LSAS–area relationship did not differ between correct and misclassified images (interaction {fp(R['interaction_lsas_logA_x_correct']['p'])}; Spearman ρ = {R['spearman_lsas_area']['correct']['rho']:.3f} vs {R['spearman_lsas_area']['incorrect']['rho']:.3f}). Representative maps for correct and misclassified predictions, for small and large lesions, are shown in [[F:gallery]].")
    rows = []
    for v, nm, dd in [('lsas', 'LSAS', 3), ('e_shuf', 'Excess LSAS (LSAS − shuffled null)', 3), ('loc_auc', 'Pixel-wise localization AUC', 3), ('frac_att', 'LSAS / oracle ceiling', 3), ('area224', 'Lesion-area fraction', 3), ('conf', 'Calibrated confidence', 3)]:
        c = R['correct_vs_incorrect'][v]; ps = ac('correct_vs_incorrect', v, 'p')
        rows.append([nm, mq(c['correct'], dd), mq(c['incorrect'], dd), fp(c['p']), f'{c["rbc"]:+.3f}', f'{cnt(ps, lambda x: x < 0.05)}/{K}'])
    M.table(['Measure', f'Correct (n = {n_c}), median (IQR)', f'Misclassified (n = {n_w}), median (IQR)', 'Mann–Whitney p', 'Rank-biserial r (correct − misclassified)', 'Seeds with p < 0.05'], rows,
            f'Explanation and confidence measures for correctly classified versus misclassified test images (reference seed {REF}; last column: consistency across all seeds).', 'Explained class = predicted class. r > 0: larger among correctly classified images.')
    kwc = R['kw_class_all']; kwe = R['kw_class_all_e_shuf']; kwo = R['kw_class_correct_only']
    rows = []
    for _, r in ct.iterrows():
        rows.append([r.cls, int(r.n_correct), f'{r.med_correct:.3f} ({r.ci_lo:.3f}–{r.ci_hi:.3f})', int(r.n_incorrect_pred), '—' if pd.isna(r.med_incorrect) else f'{r.med_incorrect:.3f}', int(r.n_all), f'{r.med_all:.3f}', f'{r.med_e_shuf_all:+.3f}', f'{r.med_area_all:.3f}'])
    M.p(f"LSAS differed across the predicted classes (Kruskal–Wallis H = {kwc['H']:.1f}, df = 6, {fp(kwc['p'])}, ε² = {kwc['eps2']:.3f}, all images; correct-only, a common restriction in this literature: H = {kwo['H']:.1f}, {fp(kwo['p'])}). The class differences persisted after subtracting the shuffled-saliency null (excess LSAS: H = {kwe['H']:.1f}, {fp(kwe['p'])}, ε² = {kwe['eps2']:.3f}), and the class-wise median area fractions in [[T:classwise]] show that class differences in raw LSAS are partly, but not entirely, differences in lesion size. The Kruskal–Wallis test on excess LSAS was significant at α = 0.05 in {cnt(ac('kw_class_all_e_shuf', 'p'), lambda v: v < 0.05)}/{K} seeds, so class differences are reproducible as a statement that classes differ; the confidence intervals of the rarer classes are too wide to interpret the ordering of individual classes.")
    M.table(['Predicted class', 'n correct', 'Median LSAS, correct (95% BCa CI)', 'n misclassified (predicted as class)', 'Median LSAS, misclassified', 'n all', 'Median LSAS, all', 'Median excess LSAS, all', 'Median area fraction, all'], rows,
            f'Class-wise LSAS (reference seed {REF}); classes are the predicted (explained) classes.')


def sec_size(M):
    R = XA[REF]; sm = R['size_measures']; pn = R['perm_null']
    M.h(2, '4.5 Lesion-size dependence: geometric audit')
    M.p(f"__Raw association.__ LSAS increased steeply with lesion size (Spearman ρ with area = {sm['lsas']['spearman_area']['rho']:.3f}; medians {sm['lsas']['med_small']:.3f}, {sm['lsas']['med_medium']:.3f} and {sm['lsas']['med_large']:.3f} for small, medium and large lesions; Kruskal–Wallis H = {sm['lsas']['kw']['H']:.1f}, {fp(sm['lsas']['kw']['p'])}, ε² = {sm['lsas']['kw']['eps2']:.2f}; all {R['n']} images; correct-only H = {sm['lsas']['kw_correct_only']['H']:.1f}). The raw effect is reproduced in every seed (ρ = {rng_s(ac('size_measures', 'lsas', 'spearman_area', 'rho'))}).")
    M.p(f"__The association is expected from geometry alone.__ Uniform saliency has LSAS = a by construction, and in a model-independent simulation on the real masks ([[T:simulation]]) even saliency placed at a random location correlates with area at ρ = {json.load(open(RES / 'lsas_scenarios_simulation.json'))['diffuse_random_location(sigma=60)']['rho_area']:.2f} (diffuse) and {json.load(open(RES / 'lsas_scenarios_simulation.json'))['concentrated_random_location(sigma=12)']['rho_area']:.2f} (concentrated). Applied to the model's own maps, the cross-image shuffled null (each mask paired with other images' maps) has ρ = {sm['null_shuf_mean']['spearman_area']['rho']:.3f} with area and reproduces the size strata almost exactly (null medians {sm['null_shuf_mean']['med_small']:.3f}, {sm['null_shuf_mean']['med_medium']:.3f}, {sm['null_shuf_mean']['med_large']:.3f} against observed {sm['lsas']['med_small']:.3f}, {sm['lsas']['med_medium']:.3f}, {sm['lsas']['med_large']:.3f}; [[T:size_audit]]). In the permutation test the observed Spearman correlation ({pn['rho_obs']:.3f}) lay within the range of the correlations obtained by re-pairing maps with masks at random (mean {pn['rho_null_mean']:.3f}, 95% range {pn['rho_null_q025']:.3f}–{pn['rho_null_q975']:.3f}; one-sided p for exceeding the null = {pn['p_greater']:.3f}), and the observed Kruskal–Wallis H ({pn['H_obs']:.0f}) was not larger than under the null (mean {pn['H_null_mean']:.0f}, 97.5th percentile {pn['H_null_q975']:.0f}; p = {pn['p_H']:.2f}). Across seeds the observed correlation exceeded the null distribution (one-sided p < 0.05) in {cnt(ac('perm_null', 'p_greater'), lambda v: v < 0.05)}/{K} seeds and the observed H did so in {cnt(ac('perm_null', 'p_H'), lambda v: v < 0.05)}/{K} seeds.")
    M.p(f"__What remains after removing the expectation.__ Excess LSAS (LSAS − shuffled null) has a median of {R['enrichment_vs_null']['all']['median_e_shuf']:+.3f} (Wilcoxon against zero {fp(R['enrichment_vs_null']['all']['p_wilcoxon'])}; {100 * R['enrichment_vs_null']['all']['frac_above_chance']:.0f}% of images above the null), so Grad-CAM++ maps are, on average, slightly more lesion-aligned than the model's typical spatial prior, but the excess is small. It is __not__ increasing with lesion size: its Spearman correlation with area was {sm['e_shuf']['spearman_area']['rho']:+.3f} ({fp(sm['e_shuf']['spearman_area']['p'])}), with a non-monotonic pattern across strata (medians {sm['e_shuf']['med_small']:+.3f}, {sm['e_shuf']['med_medium']:+.3f}, {sm['e_shuf']['med_large']:+.3f}; H = {sm['e_shuf']['kw']['H']:.1f}, ε² = {sm['e_shuf']['kw']['eps2']:.3f}, i.e. about {sm['lsas']['kw']['eps2'] / max(sm['e_shuf']['kw']['eps2'], 1e-9):.0f}-fold smaller than for raw LSAS). The ratio LSAS/a falls steeply with size (ρ = {sm['lift']['spearman_area']['rho']:.2f}) and the pixel-wise AUC, which is insensitive to area under chance, is high (median {sm['loc_auc']['med_small']:.2f}, {sm['loc_auc']['med_medium']:.2f}, {sm['loc_auc']['med_large']:.2f}) and slightly lower for large lesions (ρ = {sm['loc_auc']['spearman_area']['rho']:.2f}). In OLS models with class fixed effects and lesion-clustered errors, log-area explained {100 * R['ols_area_adj_class']['lsas']['partial_r2_logA']:.0f}% of the variance of LSAS but only {100 * R['ols_area_adj_class']['e_shuf']['partial_r2_logA']:.1f}% of the variance of excess LSAS (coefficient {R['ols_area_adj_class']['e_shuf']['coef_logA']:+.3f} per log-unit, 95% CI {R['ols_area_adj_class']['e_shuf']['ci'][0]:+.3f} to {R['ols_area_adj_class']['e_shuf']['ci'][1]:+.3f}). The toroidal-shift null, which discards the spatial prior (lesions are centred in dermoscopic images), gives a positive area gradient of excess ({sm['e_shift']['spearman_area']['rho']:+.2f}) and flags {100 * R['frac_beyond_shift_null_p05']:.0f}% of images as more lesion-aligned than chance at p < 0.05: most of the extra alignment relative to a random position is explained by the centre bias that the shuffled null retains.")
    M.p(f"__Ceiling effect for small lesions.__ Even a perfect lesion-aligned map at the 7 × 7 resolution of the target layer would reach a median LSAS of only {sm['oracle']['med_small']:.2f} for small lesions (medium {sm['oracle']['med_medium']:.2f}, large {sm['oracle']['med_large']:.2f}); observed LSAS relative to this ceiling was {sm['frac_att']['med_small']:.2f}, {sm['frac_att']['med_medium']:.2f} and {sm['frac_att']['med_large']:.2f}, still increasing with size (ρ = {sm['frac_att']['spearman_area']['rho']:.2f}), which shows that the resolution of the explanation layer, not only the model, limits LSAS for small lesions.")
    rho_gap = ac('perm_null', 'rho_obs') - ac('perm_null', 'rho_null_mean')
    M.p(f"__Conclusion of the geometric audit.__ In {cnt(ac('perm_null', 'p_greater'), lambda v: v >= 0.05)}/{K} seeds the observed LSAS–area association was indistinguishable from, or below, the geometric null; in the remaining seed(s) it exceeded the null by a statistically detectable but negligible margin (observed − null mean of Spearman ρ across seeds: {rng_s(rho_gap, 3)}). Geometry therefore accounts for essentially all of the raw association in every seed. After removing the geometric expectation, a small residual enrichment above the model's spatial prior persists (median excess {rng_s(ac('enrichment_vs_null', 'all', 'median_e_shuf'), 3)} across seeds), and its dependence on lesion size is negative in every seed (ρ = {rng_s(ac('size_measures', 'e_shuf', 'spearman_area', 'rho'), 2)}), not the increase that the raw statistic suggests.")
    S = json.load(open(RES / 'lsas_scenarios_simulation.json')); rows = []
    for k, v in S.items():
        if k == 'n_by_stratum': continue
        rows.append([k.replace('_', ' '), f'{v["rho_area"]:.3f}', f'{v["mean_small"]:.3f}', f'{v["mean_medium"]:.3f}', f'{v["mean_large"]:.3f}'])
    M.table(['Synthetic saliency scenario (real masks, n = 990)', 'Spearman ρ (LSAS, area)', 'Mean LSAS small', 'Mean LSAS medium', 'Mean LSAS large'], rows,
            'Model-independent simulation: LSAS expected under explicitly constructed saliency maps.', f'Strata sizes: small {S["n_by_stratum"]["small"]}, medium {S["n_by_stratum"]["medium"]}, large {S["n_by_stratum"]["large"]}. Blobs are isotropic Gaussians (σ in pixels).')
    rows = []
    for v, nm in [('lsas', 'Observed LSAS'), ('null_shuf_mean', 'Null: shuffled saliency (mean)'), ('null_shift_mean', 'Null: toroidal shift (mean)'), ('oracle', 'Ceiling: CAM-resolution oracle'), ('e_shuf', 'Excess LSAS (shuffled null)'), ('e_shift', 'Excess LSAS (shift null)'), ('lift', 'LSAS / area'), ('frac_att', 'LSAS / oracle'), ('loc_auc', 'Pixel-wise localization AUC')]:
        d = sm[v]; rows.append([nm, f'{d["med_small"]:.3f}', f'{d["med_medium"]:.3f}', f'{d["med_large"]:.3f}', f'{d["spearman_area"]["rho"]:+.3f}', f'{d["kw"]["H"]:.1f} ({d["kw"]["eps2"]:.3f})',
                                                                                    f'{np.nanmedian(ac("size_measures", v, "spearman_area", "rho")):+.3f} ({rng_s(ac("size_measures", v, "spearman_area", "rho"), 2)})'])
    n = R['size_n']
    M.table(['Quantity', f'Median, small (n = {n["small"]})', f'Median, medium (n = {n["medium"]})', f'Median, large (n = {n["large"]})', 'Spearman ρ with area', 'Kruskal–Wallis H (ε²)', f'ρ across seeds: median (range)'], rows,
            f'Lesion-size audit for all {R["n"]} test images (reference seed {REF}; last column summarizes all seeds).', 'All p-values for the raw statistics are < 10⁻⁸⁰ and are not informative because the statistic is dominated by geometry; see the permutation test in the text.')
    M.p(f"__Confidence.__ Calibrated confidence was unrelated to raw LSAS (Spearman ρ = {R['spearman_conf_lsas']['all']['rho']:+.3f}, {fp(R['spearman_conf_lsas']['all']['p'])}, all images; correct-only ρ = {R['spearman_conf_lsas']['correct']['rho']:+.3f}, {fp(R['spearman_conf_lsas']['correct']['p'])}). After removing the geometric expectation, however, a small positive association emerged (correct-only, excess LSAS: ρ = {R['spearman_conf_lsas']['correct_e_shuf']['rho']:+.3f}, {fp(R['spearman_conf_lsas']['correct_e_shuf']['p'])}; all images: ρ = {R['spearman_conf_lsas']['all_e_shuf']['rho']:+.3f}; across seeds ρ = {rng_s(ac('spearman_conf_lsas', 'all_e_shuf', 'rho'), 2)}). Confidence therefore carries a weak, positive signal about area-adjusted localization and is far from a reliable surrogate (ρ² ≈ {R['spearman_conf_lsas']['all_e_shuf']['rho'] ** 2:.2f}).")


def sec_faith(M):
    R = XA[REF]; F = R['faithfulness']; fm = F['mean']
    M.h(2, '4.6 Explanation faithfulness (deletion and insertion)')
    def row(bk, lab):
        f = R['faithfulness'][bk]
        return [lab, mq(f['del_cam']), mq(f['del_rand']), mq(f['del_bg_first']), mq(f['del_lesion_first']), mq(f['ins_cam']), mq(f['ins_rand']), mq(f['ins_bg_first']), mq(f['ins_lesion_first'])]
    rows = [row('mean', 'Mean-image baseline (primary)')] + ([row('blur', 'Blurred baseline (sensitivity)')] if 'blur' in F else [])
    ig_m = ac('faithfulness', 'mean', 'IG', 'median'); dg_m = ac('faithfulness', 'mean', 'DG', 'median'); ig_f = 100 * ac('faithfulness', 'mean', 'frac_IG_pos'); dg_f = 100 * ac('faithfulness', 'mean', 'frac_DG_pos')
    gap_les = ac('faithfulness', 'mean', 'DG_les', 'median'); ig_p = ac('faithfulness', 'mean', 'wilcoxon_IG_p')
    M.p(f"__Insertion.__ With the mean-image baseline, inserting Grad-CAM++-ranked patches first raised the predicted-class probability far more than inserting patches in random order in every seed (median IG {ig_m.min():.3f} to {ig_m.max():.3f}; positive in {ig_f.min():.0f}–{ig_f.max():.0f}% of images; Wilcoxon p < 10⁻¹⁵⁰ in all {K} seeds; reference seed: median IG = {mi(fm['IG'])}, IQR {fm['IG']['q1']:.3f}–{fm['IG']['q3']:.3f}). __Deletion.__ Deletion gave a different answer: the median deletion gain was positive in only {cnt(dg_m, lambda v: v > 0)}/{K} seeds (median DG {dg_m.min():+.3f} to {dg_m.max():+.3f}; reference seed {mi(fm['DG'])}, positive in {100 * fm['frac_DG_pos']:.0f}% of images) and was negative in the others, that is, removing the most salient patches first lowered the probability __less__ than removing random patches (the Wilcoxon test was significant, {'in both directions' if cnt(dg_m, lambda v: v < 0) > 0 and cnt(dg_m, lambda v: v > 0) > 0 else 'in one direction'}, in every seed). With a blurred baseline (evaluated for the reference seed only) the deletion gain was {'negative' if F['blur']['DG']['median'] < 0 else 'positive'} (median DG = {mi(F['blur']['DG'])}; positive in {100 * F['blur']['frac_DG_pos']:.0f}% of images) whereas the insertion gain remained positive (median IG = {mi(F['blur']['IG'])}). The deletion evidence therefore does not support faithfulness and varies between models and baselines, whereas the insertion evidence is consistent and moderate; such disagreement can arise when perturbed images are off the training distribution [@hooker2019,rong2022]. __Oracle-mask orderings.__ Deleting lesion-covered patches first reduced the probability far more than deleting background patches first in every seed (median AUC difference {gap_les.min():.3f} to {gap_les.max():.3f}; reference seed {mi(fm['del_lesion_first'])} vs {mi(fm['del_bg_first'])}, {fp(fm['wilcoxon_DG_les_p'])}), so in these perturbation tests the prediction depends much more on the lesion than on its surroundings.")
    M.table(['Baseline', 'Deletion AUC: Grad-CAM++ order', 'Deletion AUC: random', 'Deletion AUC: background first', 'Deletion AUC: lesion first', 'Insertion AUC: Grad-CAM++ order', 'Insertion AUC: random', 'Insertion AUC: background first', 'Insertion AUC: lesion first'], rows,
            f'Deletion and insertion AUC (median, IQR) of the predicted-class probability, all {R["n"]} test images, reference seed {REF}.', 'Lower deletion AUC and higher insertion AUC indicate greater faithfulness. Least-important-first orderings are omitted because they mirror the opposite curves by construction.')
    ka = sorted(XA)
    rows = []
    for s in ka:
        f = XA[s]['faithfulness']['mean']
        rows.append([f'Seed {s}', mi(f['DG']), f'{100 * f["frac_DG_pos"]:.0f}%', mi(f['IG']), f'{100 * f["frac_IG_pos"]:.0f}%', mi(f['DG_les']), f'{f["rho_eshuf_IG"]["rho"]:+.2f}', f'{f["rho_lsas_IG"]["rho"]:+.2f}', f'{f["rho_lsas_DG"]["rho"]:+.2f}', f'{f["rho_eshuf_DG"]["rho"]:+.2f}'])
    M.table(['Run', 'Median DG', 'DG > 0', 'Median IG', 'IG > 0', 'Median lesion-vs-background deletion gap', 'ρ(excess LSAS, IG)', 'ρ(raw LSAS, IG)', 'ρ(raw LSAS, DG)', 'ρ(excess LSAS, DG)'], rows,
            'Faithfulness gains and their relation to localization for every seed (mean-image baseline).', 'DG = AUC_del(random) − AUC_del(CAM); IG = AUC_ins(CAM) − AUC_ins(random); lesion-vs-background gap = AUC_del(background first) − AUC_del(lesion first).')
    r_ig = ac('faithfulness', 'mean', 'rho_lsas_IG', 'rho'); r_dg = ac('faithfulness', 'mean', 'rho_lsas_DG', 'rho'); e_ig = ac('faithfulness', 'mean', 'rho_eshuf_IG', 'rho'); e_dg = ac('faithfulness', 'mean', 'rho_eshuf_DG', 'rho')
    M.p(f"__Does good localization imply faithfulness?__ Raw LSAS did not. Its correlation with the deletion gain was negative in every seed (ρ = {r_dg.min():+.2f} to {r_dg.max():+.2f}; reference seed {fm['rho_lsas_DG']['rho']:+.3f}) and with the insertion gain small and of inconsistent sign (ρ = {r_ig.min():+.2f} to {r_ig.max():+.2f}; reference seed {fm['rho_lsas_IG']['rho']:+.3f}, {fp(fm['rho_lsas_IG']['p'])}), because large lesions receive high LSAS by geometry and also have low deletion gain (reference seed ρ(area, DG) = {fm['rho_area_DG']['rho']:+.2f}). Area-adjusted localization tracked insertion faithfulness moderately and consistently: excess LSAS correlated with the insertion gain at ρ = {e_ig.min():+.2f} to {e_ig.max():+.2f} (positive in {cnt(e_ig, lambda v: v > 0)}/{K} seeds), whereas its correlation with the deletion gain was {e_dg.min():+.2f} to {e_dg.max():+.2f} (positive in {cnt(e_dg, lambda v: v > 0)}/{K} seeds, near zero in some). The pixel-wise localization AUC behaved like excess LSAS (reference seed ρ with IG = {fm['rho_locauc_IG']['rho']:+.3f}). Partial correlations of raw LSAS with the gains controlling for lesion area were {fm['partial_lsas_DG_area']['rho']:+.2f} (DG) and {fm['partial_lsas_IG_area']['rho']:+.2f} (IG) in the reference seed. {('Under the blurred baseline (reference seed) the deletion gain was unrelated to excess LSAS (ρ = ' + format(F['blur']['rho_eshuf_DG']['rho'], '+.3f') + ') whereas the insertion relationship persisted (ρ = ' + format(F['blur']['rho_eshuf_IG']['rho'], '+.3f') + ').') if 'blur' in F else ''}")
    M.p(f"Misclassified images had a larger deletion gain and a smaller insertion gain than correct ones (median IG {mi(fm['IG_incorrect'])} vs {mi(fm['IG_correct'])}, {fp(fm['IG_corr_vs_incorr']['p'])}; median DG {mi(fm['DG_incorrect'])} vs {mi(fm['DG_correct'])}, {fp(fm['DG_corr_vs_incorr']['p'])}), that is, maps of wrong predictions were less able to reconstruct the prediction from a subset of the image (insertion gain lower for misclassified images with p < 0.05 in {cnt(ac('faithfulness', 'mean', 'IG_corr_vs_incorr', 'p'), lambda v: v < 0.05)}/{K} seeds).")


def sec_stability(M):
    R = XA[REF]; s = R['sts']
    M.h(2, '4.7 Stochastic explanation stability')
    st_m = ac('sts', 'median'); st_u = 100 * ac('sts', 'frac_below_05'); r_e = ac('sts', 'rho_eshuf', 'rho'); r_l = ac('sts', 'rho_lsas', 'rho'); r_a = ac('sts', 'rho_area', 'rho'); r_d = ac('sts', 'rho_DG', 'rho'); r_c = ac('sts', 'rho_conf', 'rho')
    M.p(f"Across 300 test images with 15 MC-dropout passes each, median STS was {s['median']:.3f} in the reference seed (IQR {s['q1']:.3f}–{s['q3']:.3f}; mean {s['mean']:.3f}) and {st_m.min():.3f} to {st_m.max():.3f} across the {K} seeds; {s['n_below_05']} images ({100 * s['frac_below_05']:.1f}%) fell below the 0.5 instability threshold in the reference seed ({st_u.min():.1f}–{st_u.max():.1f}% across seeds). MC-dropout predictions agreed with the deterministic prediction in {100 * s['mc_agree_mean']:.0f}% of passes on average (reference seed). Stability was moderately to strongly related to area-adjusted localization in every seed (Spearman ρ with excess LSAS = {r_e.min():+.2f} to {r_e.max():+.2f}; reference seed {s['rho_eshuf']['rho']:+.3f}, {fp(s['rho_eshuf']['p'])}), but only weakly and negatively to raw LSAS (ρ = {r_l.min():+.2f} to {r_l.max():+.2f}); it was also negatively related to lesion area (ρ = {r_a.min():+.2f} to {r_a.max():+.2f}), so part of the relation with excess LSAS may reflect shared dependence on lesion size, and the two should not be read as independent. Its relation to calibrated confidence was inconsistent in sign (ρ = {r_c.min():+.2f} to {r_c.max():+.2f}) and its relation to the deletion gain ranged from ρ = {r_d.min():+.2f} to {r_d.max():+.2f}. Stability differed between correct and misclassified images in {cnt(ac('sts', 'corr_vs_incorr', 'p'), lambda v: v < 0.05)}/{K} seeds (reference seed {fp(s['corr_vs_incorr']['p'])}). Because the perturbation acts only through the dropout layers of the head, high stability is expected and does not imply faithfulness; stability and localization are largely separate for raw LSAS (ρ = −0.157) but not for area-adjusted localization.")


def sec_skin(M, cls_agg=None):
    R = XA[REF]; S = R['skin']; ita = pd.read_csv(OUT / 'ita_all.csv'); G3 = ['I-II', 'III-IV', 'V-VI']
    M.h(2, '4.8 Skin-tone proxy analysis and darker-skin evidence')
    n1 = ita.fst_v1.value_counts(); n2 = ita.fst_v2.value_counts()
    M.p(f"Availability of darker-proxy images is the binding constraint. Across all 10,015 HAM10000 images the ITA proxy classified {n1['I-II']:,} / {n1['III-IV']:,} / {n1['V-VI']:,} images as I–II / III–IV / V–VI (v1, direct definition), and {n2['I-II']:,} / {n2['III-IV']:,} / {n2['V-VI']:,} with the vignette- and halo-robust variant (v2); the darkest proxy stratum is therefore only {100 * n1['V-VI'] / len(ita):.1f}% (v1) or {100 * n2['V-VI'] / len(ita):.1f}% (v2) of the dataset. Among the 990 test images the strata contained {S['v1_all']['n']['I-II']} / {S['v1_all']['n']['III-IV']} / {S['v1_all']['n']['V-VI']} images (v1) and {S['v2_all']['n']['I-II']} / {S['v2_all']['n']['III-IV']} / {S['v2_all']['n']['V-VI']} (v2); restricted to correct predictions only (a common restriction in this literature) the darkest stratum held {S['v1_correct_only']['n']['V-VI']} (v1) and {S['v2_correct_only']['n']['V-VI']} (v2) images. The ITA v1 and v2 definitions disagree on the assignment of {int((ita.fst_v1 != ita.fst_v2).sum()):,} images ({100 * (ita.fst_v1 != ita.fst_v2).mean():.1f}%), which shows that the proxy is sensitive to its definition, most strongly for the darkest stratum (377 vs 237 images); it was not verified against any independent skin-type label.")
    M.p("__Search for stronger evidence.__ The only other project data with skin-tone information is PAD-UFES-20 (clinician-assigned Fitzpatrick types), but after class mapping it holds only 9 images of Fitzpatrick V–VI among 2,106 (Section 4.9), and its smartphone images have no lesion masks, so LSAS cannot be computed. Purpose-built diverse datasets (for example Fitzpatrick 17k and the Diverse Dermatology Images set [@groh2021,daneshjou2022]) are clinical photographs without lesion segmentations, so neither LSAS nor a like-for-like evaluation of a dermoscopy-trained model is possible without confounding skin tone with imaging modality. No dataset that would raise the number of darker-skin dermoscopic images with masks was found within the supplied materials; the darker-skin question is therefore answered by an uncertainty-aware analysis of the available images and is explicitly limited.")
    rows = []
    for ver, lab in [('v1', 'v1 (original)'), ('v2', 'v2 (vignette/halo-robust)')]:
        for sub, nm in [('correct_only', 'correct only'), ('all', 'all images')]:
            r = S[f'{ver}_{sub}']
            for gname in G3:
                perf = r.get('perf_by_group', {}).get(gname)
                rows.append([f'{lab}, {nm}', gname, r['n'][gname], f'{r["med"][gname]:.3f}', f'{r["med_e_shuf"][gname]:+.3f}', '' if perf is None else f'{perf["acc"]:.3f} ({perf["acc_ci_clopper_pearson"][0]:.2f}–{perf["acc_ci_clopper_pearson"][1]:.2f})',
                             '' if gname != 'I-II' else f'{fp(r["kw_lsas"]["p"])}; ε² = {r["kw_lsas"]["eps2"]:.3f}', '' if gname != 'I-II' else f'{fp(r["kw_e_shuf"]["p"])}; ε² = {r["kw_e_shuf"]["eps2"]:.3f}'])
    r1 = S['v1_correct_only']; r1a = S['v1_all']; mde = S['mde_correct_only']
    sk = lambda ver, sub, *p: np.array([g(XA[q]['skin'][f'{ver}_{sub}'], *p) for q in sorted(XA)], float)
    kwc_p = sk('v1', 'correct_only', 'kw_lsas', 'p'); kwe_p = sk('v1', 'all', 'kw_e_shuf', 'p'); rho_e = sk('v1', 'all', 'spearman_ita_eshuf', 'rho'); rho_e_p = sk('v1', 'all', 'spearman_ita_eshuf', 'p')
    adj_c = sk('v1', 'all', 'ols_eshuf_adj', 'coef_ita'); adj_p = sk('v1', 'all', 'ols_eshuf_adj', 'p')
    lowest = [int(XA[q]['skin']['v1_all']['med']['V-VI'] < min(XA[q]['skin']['v1_all']['med']['I-II'], XA[q]['skin']['v1_all']['med']['III-IV'])) for q in sorted(XA)]
    v1c = R['skin']['v1_correct_only']; v1a = R['skin']['v1_all']; mde = R['skin']['mde_correct_only']
    dref = pd.read_csv(RES / 'ref_per_image_enriched.csv'); ga = dref[dref.fst_v1 == 'I-II']; gb = dref[dref.fst_v1 == 'V-VI']
    from scipy import stats as _st
    p_area = _st.mannwhitneyu(ga.area224, gb.area224).pvalue
    M.p(f"__Results.__ In the original design (correct predictions, v1 proxy) the Kruskal–Wallis test on raw LSAS across the three strata was significant at α = 0.05 in {cnt(kwc_p, lambda v: v < 0.05)}/{K} seeds (p range {kwc_p.min():.1e}–{kwc_p.max():.2f}; reference seed {REF}: {fp(v1c['kw_lsas']['p'])}). The darkest proxy stratum had the lowest median raw LSAS in {sum(lowest)}/{K} seeds (reference seed: {v1a['med']['V-VI']:.3f} vs {v1a['med']['I-II']:.3f} for I–II), but this direction follows lesion geometry: in the reference seed the darkest-stratum lesions were smaller (median area fraction {gb.area224.median():.3f} vs {ga.area224.median():.3f} for I–II; Mann–Whitney {fp(p_area)}), and the shuffled-saliency null differed by a similar amount (median {gb.null_shuf_mean.median():.3f} vs {ga.null_shuf_mean.median():.3f}), whereas the continuous ITA–area correlation is near zero (ρ = {v1a['spearman_ita_area']['rho']:+.3f}) because the stratum difference is confined to the small darkest group. After subtracting the geometric expectation, excess LSAS differed significantly between strata in {cnt(kwe_p, lambda v: v < 0.05)}/{K} seeds (all-image analysis; p range {kwe_p.min():.1e}–{kwe_p.max():.2f}); the association of continuous ITA with excess LSAS ranged from ρ = {rho_e.min():+.2f} to {rho_e.max():+.2f} across seeds and changed sign between seeds (significant at α = 0.05 in {cnt(rho_e_p, lambda v: v < 0.05)}/{K} seeds, with both signs), and the adjusted slope (excess LSAS on ITA, log area and class) ranged from {adj_c.min():+.5f} to {adj_c.max():+.5f} per degree (p < 0.05 in {cnt(adj_p, lambda v: v < 0.05)}/{K} seeds; reference seed {v1a['ols_eshuf_adj']['coef_ita']:+.5f}, 95% CI {v1a['ols_eshuf_adj']['ci'][0]:+.5f} to {v1a['ols_eshuf_adj']['ci'][1]:+.5f}). Where a seed produced a significant difference, it was not monotonic in tone and did not replicate in the other seeds. With the vignette-robust v2 proxy the raw contrasts were significant in {cnt(sk('v2', 'all', 'kw_lsas', 'p'), lambda v: v < 0.05)}/{K} seeds. The darkest stratum is too small for anything but a large effect: with {mde['n_I_II']} (I–II) versus {mde['n_V_VI']} (V–VI) correct predictions the minimum detectable standardized difference at 80% power is d = {mde['cohen_d_80pct']:.2f}, about {mde['lsas_units']:.3f} LSAS units (SD {mde['lsas_sd']:.3f}); the rank-biserial effect of I–II versus V–VI on raw LSAS was {v1c['pairwise_lsas'][1]['rbc']:+.2f} in the reference seed with a Holm-adjusted p of {v1c['pairwise_lsas'][1]['p_holm']:.2f}. Accuracy by proxy stratum is shown in [[T:skin]]; the intervals are wide.")
    M.p("__Interpretation.__ The evidence is inconclusive: it is neither absence of an effect nor evidence of one. The raw LSAS difference in the darkest stratum is directionally consistent but explained by lesion geometry; area-adjusted associations are small, change sign between independently trained models and reach nominal significance in isolated seeds, so findings from a single run in a stratum of about 30 images should not be trusted in either direction. The analyses do not show that explanations are fair across skin tones: the proxy is not a clinical skin type, the darkest stratum is tiny and definition-dependent, power is limited to large effects, and no independent darker-skin dermoscopic images exist here. 'No consistent association detected', 'insufficient evidence' and 'fairness validated' are different statements, and only the first is supported.")
    M.table(['Proxy version, subset', 'ITA stratum', 'n', 'Median LSAS', 'Median excess LSAS', 'Accuracy (95% Clopper–Pearson)', 'Kruskal–Wallis, LSAS', 'Kruskal–Wallis, excess LSAS'], rows,
            f'Skin-tone-proxy analysis (reference seed {REF}); strata are ITA proxies, not Fitzpatrick types.', 'Accuracy by stratum is reported for the all-image analysis only.')


def sec_external(M):
    seeds = sorted(PA); k = len(seeds); R = PA[REF]
    def a(key, m): return np.array([PA[s][key][m] for s in seeds], float)
    def line(key, m, d=3): v = a(key, m); return ms(v, d)
    M.h(2, '4.9 External evaluation on PAD-UFES-20: mapping versus domain shift')
    facts = json.load(open(RES / 'pad_facts.json'))
    M.p(f"__Audit of the mapping.__ PAD-UFES-20 has {facts['n_total']:,} images from {facts['n_patients']:,} patients (BCC {facts['diag_counts']['BCC']}, ACK {facts['diag_counts']['ACK']}, NEV {facts['diag_counts']['NEV']}, SEK {facts['diag_counts']['SEK']}, SCC {facts['diag_counts']['SCC']}, MEL {facts['diag_counts']['MEL']}). Excluding SCC (no HAM10000 class) leaves {facts['n_mapped']:,} images of {facts['n_patients_mapped']:,} patients (AKIEC/ACK {facts['mapped_counts']['AKIEC']}, BCC {facts['mapped_counts']['BCC']}, NV/NEV {facts['mapped_counts']['NV']}, BKL/SEK {facts['mapped_counts']['BKL']}, MEL {facts['mapped_counts']['MEL']}); {100 * facts['biopsy_proven_frac']:.0f}% are biopsy-proven. The class prevalence differs sharply from HAM10000 (AKIEC {100 * R['prevalence']['PAD']['AKIEC']:.0f}% and BCC {100 * R['prevalence']['PAD']['BCC']:.0f}% vs {100 * R['prevalence']['HAM5']['AKIEC']:.0f}% and {100 * R['prevalence']['HAM5']['BCC']:.0f}%; NV {100 * R['prevalence']['PAD']['NV']:.0f}% vs {100 * R['prevalence']['HAM5']['NV']:.0f}%; MEL {100 * R['prevalence']['PAD']['MEL']:.1f}% vs {100 * R['prevalence']['HAM5']['MEL']:.0f}% of the five mapped classes). The label correspondences are imperfect: ACK (clinical actinic keratosis) is mapped to AKIEC, which in HAM10000 also includes Bowen disease/intraepithelial carcinoma, and SEK (seborrheic keratosis) is only one component of BKL. Images are smartphone photographs with variable native size (median {facts['native_res_median'][0]:.0f} × {facts['native_res_median'][1]:.0f} px, range {facts['native_res_min'][0]}–{facts['native_res_max'][0]} px) and {facts['n_gt_1024']:,} of {facts['n_total']:,} were downscaled to 1,024 px before hair removal (see below).")
    rows = []
    labs = [('A_HAM_test_7class', 'A. HAM test, 7 classes (all 990 images)'), ('B_HAM_test_5class_images_7way_output', 'B. HAM test restricted to the 5 mappable classes, 7-way output (population effect)'), ('C_HAM_test_5class_images_5way_output', 'C. As B, output restricted to 5 classes (label-space effect)'),
            ('D_PAD_mapped_7way_output', 'D. PAD-UFES-20, 7-way output (original protocol)'), ('E_PAD_mapped_5way_output', 'E. PAD-UFES-20, 5-way output'), ('F_HAM_test_3class_3way', 'F. HAM test, BCC/MEL/NV only (3-way)'), ('G_PAD_3class_3way', 'G. PAD-UFES-20, BCC/MEL/NV only (3-way)')]
    for key, lab in labs:
        rows.append([lab, R[key]['n'], line(key, 'acc'), line(key, 'bacc'), line(key, 'f1_present'), line(key, 'f1_7zero'), 'n/a' if key in ('B_HAM_test_5class_images_7way_output', 'D_PAD_mapped_7way_output') else line(key, 'auroc'), line(key, 'ece'), line(key, 'mean_conf')])
    rows.insert(5, ['P. HAM per-class recalls re-weighted to PAD prevalence (5-way)', '—', ms(np.array([PA[s]['prevalence_reweighted_HAM_acc_5way'] for s in seeds])), '—', '—', '—', '—', '—', '—'])
    A = a('A_HAM_test_7class', 'acc'); B = a('B_HAM_test_5class_images_7way_output', 'acc'); C = a('C_HAM_test_5class_images_5way_output', 'acc'); P = np.array([PA[s]['prevalence_reweighted_HAM_acc_5way'] for s in seeds]); E = a('E_PAD_mapped_5way_output', 'acc'); D = a('D_PAD_mapped_7way_output', 'acc')
    f7c = a('C_HAM_test_5class_images_5way_output', 'f1_7zero'); f5c = a('C_HAM_test_5class_images_5way_output', 'f1_present'); f5e = a('E_PAD_mapped_5way_output', 'f1_present')
    M.p(f"__Decomposition of the drop.__ [[T:pad_decomp]] evaluates the same models on progressively changed populations. Restricting the HAM10000 test set to images of the five mappable classes changed accuracy by only {np.mean(B - A):+.3f} (population effect), and restricting the output space to those five classes by a further {np.mean(C - B):+.3f} (label-space effect). Re-weighting the HAM10000 per-class recalls to PAD-UFES-20's class prevalence lowered the expected accuracy by {np.mean(P - C):+.3f} (prevalence effect; {ms(P)}). The remaining drop to the observed PAD-UFES-20 accuracy ({ms(E)} with 5-way output; {ms(D)} with 7-way output) is {np.mean(E - P):+.3f}; it combines appearance shift and label-semantics mismatch and cannot be attributed to a single cause, but neither class mapping nor prevalence accounts for it. The macro-F1 used in the original comparison (0.686 → 0.176) mixed real degradation with a definitional artefact: computed over all seven classes with absent classes counted as zero, macro-F1 on even the HAM10000 five-class subset is {ms(f7c)} instead of {ms(f5c)} over the five classes present, so about {np.mean(f5c - f7c):.2f} of the apparent macro-F1 drop is due to the definition. Like-for-like (five present classes), macro-F1 falls from {ms(f5c)} to {ms(f5e)}. In a three-class comparison restricted to BCC, MEL and NV, whose labels correspond best, balanced accuracy still falls from {line('F_HAM_test_3class_3way', 'bacc')} to {line('G_PAD_3class_3way', 'bacc')}, and MEL recall from {ms(np.array([PA[s]['F_HAM_test_3class_3way']['recall']['MEL'] for s in seeds]))} to {ms(np.array([PA[s]['G_PAD_3class_3way']['recall']['MEL'] for s in seeds]))}. Calibration deteriorated in parallel: mean confidence was {line('E_PAD_mapped_5way_output', 'mean_conf')} against an accuracy of {ms(E)}, an ECE of {line('E_PAD_mapped_5way_output', 'ece')}, and refitting the temperature on PAD-UFES-20 would require T = {ms(np.array([PA[s]['PAD_refit_T_5way'] for s in seeds]), 2)} (vs. {np.mean(cls_T()):.2f}), i.e. a strongly softened output; even then ECE would be only {ms(np.array([PA[s]['PAD_5way_ECE_after_T_refit'] for s in seeds]), 3)}.")
    M.table(['Evaluation set', 'n', 'Accuracy', 'Balanced accuracy', 'Macro-F1, present classes', 'Macro-F1, 7 classes (absent = 0)', 'Macro-AUROC', 'ECE', 'Mean confidence'], rows,
            f'Stepwise decomposition of the internal-to-external performance drop (mean ± SD over {k} seeds).', 'AUROC is defined only when the output space equals the label space. Balanced accuracy is not affected by class prevalence.')
    if DG:
        dgs = sorted(DG); L = lambda key, m, i: np.array([DG[s]['adaptation_ladder'][key][m][i] for s in dgs])
        rows = []
        for key, lab in [('zero_shot', 'Zero-shot (no PAD data)'), ('bias_only', '+ 5-parameter class-bias correction (label/prior shift proxy)'), ('probe_1024', '+ linear probe on frozen 1,024-d backbone features'), ('probe_512', '+ linear probe on frozen 512-d head features')]:
            rows.append([lab, ms(L(key, 'acc', 0)), ms(L(key, 'bacc', 0)), ms(L(key, 'f1', 0))])
        ref = np.array([DG[s]['HAM_internal_probe_reference']['bacc'][0] for s in dgs]); refa = np.array([DG[s]['HAM_internal_probe_reference']['acc'][0] for s in dgs]); reff = np.array([DG[s]['HAM_internal_probe_reference']['f1'][0] for s in dgs])
        rows.append(['Reference: same probe trained/tested within HAM10000 (5 classes, lesion-level 30/70 splits)', ms(refa), ms(ref), ms(reff)])
        dc = np.array([DG[s]['domain_classifier_auroc']['mean'] for s in dgs]); fr = np.array([DG[s]['frechet']['ham_vs_pad'] for s in dgs]); fr0 = np.array([DG[s]['frechet']['ham_half_vs_half'] for s in dgs])
        hd = DG[dgs[0]]['hair_removal_deviation']; ist = json.load(open(RES / 'domain_gap_42.json'))['image_stats']
        M.p(f"__Measured shift.__ A logistic-regression domain classifier on backbone features separated HAM10000 test images from PAD-UFES-20 images almost perfectly (cross-validated AUROC {ms(dc, 4)}), and the Fréchet distance between the feature distributions was {ms(fr, 0)} versus {ms(fr0, 0)} between two random halves of the HAM10000 test set. Simple image statistics differ markedly as well (standardized differences, PAD minus HAM: luminance L* d = {ist['L']['cohen_d']:+.2f}, blue channel d = {ist['B']['cohen_d']:+.2f}, Laplacian sharpness d = {ist['lap_var']['cohen_d']:+.2f}, dark-border fraction d = {ist['dark_frac']['cohen_d']:+.2f}), and the datasets differ in device, illumination, background, field of view (no dermoscopic vignette) and population. The adaptation ladder ([[T:pad_ladder]]; patient-level 30%/70% splits, 20 repeats) indicates where the loss sits. A five-parameter class-bias correction fitted on PAD data did not restore balanced accuracy (it optimizes likelihood under PAD's skewed prevalence and lowers balanced accuracy), so the drop is not merely a prior-shift artefact; a linear probe on the frozen features fitted on 30% of PAD patients raised balanced accuracy to {ms(L('probe_1024', 'bacc', 0))}, comparable to the same probe within HAM10000 ({ms(ref)}) under an equally small adaptation set. The features therefore retain class-relevant information across the domains, while the source-trained decision layer does not transfer; this supports a decision-boundary/appearance shift interpretation but does not identify individual causes or show that an adapted model would be clinically adequate.")
        M.table(['Adaptation level (PAD evaluation patients, 5 classes)', 'Accuracy', 'Balanced accuracy', 'Macro-F1'], rows, f'Adaptation ladder on PAD-UFES-20 (mean ± SD across the {len(dgs)} seed models of the mean over 20 patient-level splits).')
        M.p(f"__Effect of the resolution cap.__ Downscaling images above 1,024 px before hair removal changed predictions for {100 * (1 - hd['agree_all']):.0f}% of PAD images ({100 * (1 - hd['agree_big_images']):.0f}% of the {hd['n_big']} large images) relative to resize-only processing without hair removal, and accuracy differed by {100 * (hd['acc_resize_only'] - hd['acc_with_hair_removal']):+.1f} percentage points (seed {dgs[0]}); this is far too small to explain the drop.")
    fs = R['PAD_by_fitzpatrick_acc_5way']; rows = [[k_, v['n'], f'{v["acc"]:.3f}', f'{v["ci"][0]:.2f}–{v["ci"][1]:.2f}'] for k_, v in fs.items()]
    M.p(f"__Skin tone in PAD-UFES-20.__ Fitzpatrick types are recorded for {facts['n_mapped'] - fs['missing']['n']:,} of the mapped images, but only {fs['V-VI']['n']} images are Fitzpatrick V–VI, so accuracy for the darkest types has an interval too wide to be informative ([[T:pad_fitz]]).")
    M.table(['Fitzpatrick type (PAD-UFES-20, mapped images)', 'n', 'Accuracy (seed 42, 5-way)', '95% CI'], rows, 'PAD-UFES-20 accuracy by recorded Fitzpatrick type (reference seed).')


def cls_T():
    df = pd.read_csv(RES / 'cls_per_seed.csv'); return df['T'].values
